// Gate: explainable rules, every decision carries its reason.
const a = $('Fold URL').first().json;
const cfg = $('Config').first().json.config;
const e = a.enrichment || {};

const ioc_hits = [];
if (e.ip && e.ip.abuseipdb && e.ip.abuseipdb.malicious) ioc_hits.push('abuseipdb_ip:' + e.ip.abuseipdb.confidence);
