  if (parsed) {
    const need = ['verdict', 'confidence', 'confidence_score', 'evidence', 'justification', 'primary_driver', 'suggested_action', 'investigation_query'];
    const missing = need.filter(k => !(k in parsed));
    if (missing.length) { error = 'AI output missing: ' + missing.join(', '); }
    else llm_ok = true;
