const cs = Number(r.confidence_score);
const confidence_score = Number.isFinite(cs) ? Math.max(0, Math.min(100, Math.round(cs))) : 0;
const ids = [base.rule_id && ('rule_id:"' + base.rule_id + '"'), base.src_ip && ('src_ip:"' + base.src_ip + '"'),
             base.user && ('user:"' + base.user + '"'), base.agent_name && ('agent_name:"' + base.agent_name + '"'),
             base.file_hash && ('hash:"' + base.file_hash + '"')].filter(Boolean).join(' OR ');

let evidence, justification, primary_driver, suggested_action, investigation_query;
if (llm_ok) {
  evidence = list(r.evidence); justification = String(r.justification); primary_driver = String(r.primary_driver);
  suggested_action = list(r.suggested_action); investigation_query = String(r.investigation_query);
} else {
  evidence = ['AI analysis unavailable or invalid: ' + outcome_reason,
              'Rule ' + base.rule_id + ' level ' + base.rule_level + ' on ' + base.agent_name,
              'Gate reasons: ' + base.gate_reasons.join(', ')].concat(base.ioc_hits.map(h => 'IOC hit: ' + h));
  justification = 'Automated analysis did not produce a usable verdict, so this alert is routed for manual review.';
  primary_driver = 'N/A - analysis unavailable'; suggested_action = ['Manually review the alert and enrichment data'];
  investigation_query = ids;
}
if (floor_applied) evidence.unshift('Verdict floor applied: AI said false_positive, raised to needs_review (' + outcome_reason + ')');

const out = { ...base, verdict, verdict_original, confidence, confidence_score, evidence, justification, primary_driver,
  suggested_action, investigation_query, llm_ok, floor_applied, outcome: verdict,
  outcome_reason: outcome_reason || (base.gate_reasons || []).join(', ') };
delete out.raw_alert; delete out.llm_input; delete out.llm_payload;

const emoji = { true_positive: ':rotating_light:', needs_review: ':mag:', false_positive: ':white_check_mark:' }[verdict];
const bullets = a => a.slice(0, 10).map(x => '- ' + x).join('\n');
out.slack_text = emoji + ' *SOC Alert:* ' + base.rule_description + '\n\n*Verdict:* ' + verdict + (floor_applied ? ' (floored from false_positive)' : '') +
  '\n*Confidence:* ' + confidence + ' (' + confidence_score + ')\n*Host:* ' + base.agent_name + '\n*User:* ' + (base.user || 'n/a') +
  '\n*Source IP:* ' + (base.src_ip || 'n/a') + ' (' + base.ip_category + ')\n*Why it reached the AI:* ' + base.gate_reasons.join(', ') +
  (base.suppressed_prior ? '\n*Repeats suppressed earlier:* ' + base.suppressed_prior : '') +
  (base.lookup_failures.length ? '\n*Lookup failures:* ' + base.lookup_failures.join(', ') : '') +
  '\n\n*Evidence:*\n' + bullets(evidence) + '\n\n*Primary Driver:*\n' + primary_driver +
  '\n\n*Suggested Actions:*\n' + bullets(suggested_action) + '\n\n*Investigation Query:*\n```' + investigation_query + '```';
out.jira_summary = 'SOC Alert: ' + base.rule_description + ' [' + verdict + ']';
out.jira_description = justification + '\n\nEvidence:\n' + bullets(evidence) + '\n\nSuggested Actions:\n' + bullets(suggested_action) + '\n\nInvestigation Query:\n' + investigation_query;
out.jira_priority_id = verdict === 'true_positive' ? '2' : '3';
return { json: out };

// One flat row per alert outcome. Column order below = sheet header order.
const j = $json;
const s = v => (v === undefined || v === null) ? '' : String(v);
return { json: {
  logged_at: new Date().toISOString(), alert_time: s(j.timestamp), outcome: s(j.outcome || 'unknown'), reason: s(j.outcome_reason),
  gate_reasons: (j.gate_reasons || []).join(';'), verdict: s(j.verdict), confidence: s(j.confidence), floor_applied: s(j.floor_applied),
  rule_id: s(j.rule_id), rule_level: s(j.rule_level), rule_description: s(j.rule_description), agent_name: s(j.agent_name),
  user: s(j.user), src_ip: s(j.src_ip), ip_category: s(j.ip_category), file_hash: s(j.file_hash), domain: s(j.domain), url: s(j.url),
  ioc_hits: (j.ioc_hits || []).join(';'), lookup_failures: (j.lookup_failures || []).join(';'),
  suppressed_prior: s(j.suppressed_prior), fingerprint: s(j.fingerprint).slice(0, 12), malformed_excerpt: s(j.body_excerpt)
} };
